use std::{path::Path, process::ExitCode};

use clap::Parser;

// Generated by `build.rs` from `programs/manifest.json`, which is the single
// source of truth for programs to benchmark and test.
include!(concat!(env!("OUT_DIR"), "/programs.rs"));

#[derive(Clone, Copy, clap::ValueEnum)]
enum CompilerArg {
    CargoBuildSbpf,
    CargoBuildSbf,
}

impl From<CompilerArg> for harness::Compiler {
    fn from(value: CompilerArg) -> Self {
        match value {
            CompilerArg::CargoBuildSbpf => Self::CargoBuildSbpf,
            CompilerArg::CargoBuildSbf => Self::CargoBuildSbf,
        }
    }
}
#[derive(Parser)]
struct Arguments {
    /// Compiler used to build the programs.
    #[arg(long, value_enum, default_value = "cargo-build-sbpf")]
    compiler: CompilerArg,

    /// Build the selected compiler locally from the current root.
    #[arg(long)]
    local: bool,

    /// Comma-separated list of programs to run (defaults to all).
    #[arg(long, value_delimiter = ',', value_name = "NAMES")]
    programs: Vec<String>,

    /// Comma-separated list of programs to skip (defaults to none).
    #[arg(
        long,
        value_delimiter = ',',
        value_name = "NAMES",
        conflicts_with = "programs"
    )]
    skip_programs: Vec<String>,
}

fn main() -> ExitCode {
    let arguments = Arguments::parse();
    let local_binary = if arguments.local {
        match harness::build_local_compiler(arguments.compiler.into()) {
            Ok(binary) => Some(binary),
            Err(error) => {
                eprintln!("error: {error}");
                return ExitCode::FAILURE;
            }
        }
    } else {
        None
    };
    match harness::run(
        Path::new(env!("CARGO_MANIFEST_DIR")),
        arguments.compiler.into(),
        local_binary,
        &registrations(),
        &clean(&arguments.programs),
        &clean(&arguments.skip_programs),
    ) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::FAILURE
        }
    }
}

fn clean(names: &[String]) -> Vec<String> {
    names
        .iter()
        .map(|name| name.trim().to_owned())
        .filter(|name| !name.is_empty())
        .collect()
}
